import React from 'react';

function WeddingService() {
  return (
    <div className="container py-4">
      <h2 className="text-center text-danger mb-4">Dịch vụ tổ chức tiệc cưới</h2>
      <p>
        Chúng tôi mang đến trải nghiệm tiệc cưới đẳng cấp với không gian trang trí sang trọng, thực đơn đa dạng và đội ngũ chuyên nghiệp.
      </p>
      <ul>
        <li>Trang trí theo chủ đề (Luxury, Vintage, Rustic...)</li>
        <li>Thực đơn Âu – Á linh hoạt</li>
        <li>MC, ban nhạc, nghi lễ cưới đầy đủ</li>
        <li>Chụp ảnh, quay phim, livestream sự kiện</li>
      </ul>
      <p>Liên hệ ngay để đặt lịch tư vấn và nhận ưu đãi!</p>
    </div>
  );
}

export default WeddingService;
